package spilmansidecar

// Cross-language contract test: this Go client against the REAL sidecar binary.
//
// Every other test in this package uses a Go fixture that I wrote, so it can
// only prove the client agrees with my own understanding of the protocol. This
// file proves the two implementations agree with each other: the golden values
// come from the pinned Rust protocol crate (fixtures/registration_golden.json
// is generated by `cargo run --example golden_fixture`), the refusals come from
// the Rust validator, and the assertions here are about the WIRE — that the
// codes cross intact and the derived values arrive unchanged.
//
// Skipped unless SPILMAN_SIDECAR_BIN names a built sidecar, so `go test ./...`
// stays fast; tests/contract/spilman-crosslang_test.sh builds the binary and
// runs this file for real.

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"testing"
)

// goldenFixture mirrors sidecar/spilman/tests/fixtures/registration_golden.json.
type goldenFixture struct {
	// Comment is a JSON array of strings in the generated fixture.
	Comment           []string                   `json:"_comment"`
	ReceiverSecretHex string                     `json:"receiver_secret_hex"`
	SenderSecretHex   string                     `json:"sender_secret_hex"`
	TrustedMintURL    string                     `json:"trusted_mint_url"`
	TrustedKeysetInfo json.RawMessage            `json:"trusted_keyset_info"`
	NestedParamsJSON  string                     `json:"nested_params_json"`
	Registration      Registration               `json:"registration"`
	Expected          map[string]json.RawMessage `json:"expected"`
}

// shortRealSidecar starts the real binary on a SHORT socket path.
//
// AF_UNIX caps a path at ~108 bytes and t.TempDir() embeds the test name, so a
// table-driven subtest overflows the limit and the sidecar refuses to bind. That
// refusal is correct behaviour from the binary and a harness bug here, so the
// socket gets an abbreviated directory instead of the test growing an exemption.
func shortRealSidecar(t *testing.T) *sidecarProcess {
	t.Helper()
	bin := os.Getenv(SPILMAN_SIDECAR_BIN_ENV)
	if bin == "" {
		t.Skip("set " + SPILMAN_SIDECAR_BIN_ENV + " to the built sidecar to run the cross-language check")
	}
	dir, err := os.MkdirTemp("", "sb")
	if err != nil {
		t.Fatalf("tempdir: %v", err)
	}
	if err := os.Chmod(dir, 0o700); err != nil {
		t.Fatalf("chmod: %v", err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(dir) })
	sock := filepath.Join(dir, "s.sock")
	if len(sock) > 100 {
		t.Fatalf("socket path too long for AF_UNIX: %d bytes: %s", len(sock), sock)
	}
	return newSidecarProcess(t, bin, dir, sock)
}

func loadGolden(t *testing.T) goldenFixture {
	t.Helper()
	// The fixture lives with the Rust crate: it is generated there and consumed
	// here, so there is exactly one copy and it cannot drift into two.
	path := filepath.Join("..", "..", "sidecar", "spilman", "tests", "fixtures", "registration_golden.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read golden fixture %s: %v", path, err)
	}
	var g goldenFixture
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatalf("parse golden fixture: %v", err)
	}
	if g.ReceiverSecretHex == "" || g.NestedParamsJSON == "" || len(g.Registration.Mint) == 0 {
		t.Fatalf("golden fixture is incomplete: %+v", g)
	}
	return g
}

func (g goldenFixture) request() RegistrationRequest {
	return RegistrationRequest{
		ReceiverSecretHex: g.ReceiverSecretHex,
		TrustedMintURL:    g.TrustedMintURL,
		TrustedKeysetInfo: g.TrustedKeysetInfo,
		Registration:      g.Registration,
		ParamsJSON:        g.NestedParamsJSON,
		// Well before expiry_timestamp in the fixture, so the happy path is not
		// accidentally testing expiry.
		NowUnix: 1700000000,
	}
}

func (g goldenFixture) expectedString(t *testing.T, key string) string {
	t.Helper()
	raw, ok := g.Expected[key]
	if !ok {
		t.Fatalf("golden fixture has no expected %q", key)
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		t.Fatalf("expected %q is not a string: %v", key, err)
	}
	return s
}

// TestRealSidecarValidatesTheGoldenRegistration is the cross-language happy
// path: the Rust side derives, the Go side receives, and the values must be
// identical to the ones the Rust test asserts.
func TestRealSidecarValidatesTheGoldenRegistration(t *testing.T) {
	p := shortRealSidecar(t)
	c := p.client(t)
	g := loadGolden(t)

	got, err := c.ValidateRegistration(context.Background(), "op-golden", g.request())
	if err != nil {
		t.Fatalf("validate golden registration: %v", err)
	}

	if want := g.expectedString(t, "channel_id"); got.ChannelID != want {
		t.Fatalf("channel_id: got %q want %q (the two implementations disagree on derivation)", got.ChannelID, want)
	}
	if want := g.expectedString(t, "canonical_params_json"); got.CanonicalParamsJSON != want {
		t.Fatalf("canonical_params_json: got %q want %q", got.CanonicalParamsJSON, want)
	}
	if want := g.expectedString(t, "receiver_pubkey"); got.ReceiverPubkey != want {
		t.Fatalf("receiver_pubkey: got %q want %q", got.ReceiverPubkey, want)
	}
	if want := g.expectedString(t, "sender_pubkey"); got.SenderPubkey != want {
		t.Fatalf("sender_pubkey: got %q want %q", got.SenderPubkey, want)
	}
	if got.MintFundsAsserted {
		t.Fatal("a successful validation must never assert anything about mint funds")
	}
	if got.TrustSignal != TrustSignalRegistrationValidated {
		t.Fatalf("trust signal: got %q", got.TrustSignal)
	}
}

// TestRealSidecarRefusalCodesCrossIntact drives every refusal the contract
// names against the real Rust validator, so a code renamed on one side is
// caught here rather than by an operator reading a log.
func TestRealSidecarRefusalCodesCrossIntact(t *testing.T) {
	p := shortRealSidecar(t)
	g := loadGolden(t)

	cases := []struct {
		name   string
		mutate func(*RegistrationRequest)
		want   string
	}{
		{
			// (a) The receiver pubkey is not the one derived from the secret:
			// a payee trying to point a channel at someone else's key.
			name: "mismatched_receiver_pubkey",
			mutate: func(r *RegistrationRequest) {
				r.Registration.ReceiverPubkey = "02" + "11" + r.Registration.ReceiverPubkey[4:]
			},
			want: RefusalReceiverMismatch,
		},
		{
			// (b) nested params name a DIFFERENT mint while the outer record and
			// the trusted URL both say the right one. This is the reviewer's
			// "nested params" gap: the outer fields agree, so only parsing the
			// nested blob catches it.
			name: "nested_mint_substitution",
			mutate: func(r *RegistrationRequest) {
				r.ParamsJSON = replaceJSONField(t, r.ParamsJSON, "mint", "https://evil.example")
			},
			// `mint_not_trusted`, not `nested_params_mismatch`: the sidecar
			// compares the nested mint to the TRUSTED url, so a substitution is
			// reported as a mint problem rather than as self-inconsistency.
			// The two need different operator actions, so the codes differ.
			want: RefusalMintNotTrusted,
		},
		{
			// (b) nested params name a different keyset id.
			name: "nested_keyset_substitution",
			mutate: func(r *RegistrationRequest) {
				r.ParamsJSON = replaceJSONField(t, r.ParamsJSON, "keyset_id", "00deadbeefdeadbe")
			},
			want: RefusalNestedMismatch,
		},
		{
			// (b) nested capacity disagrees with the outer capacity: the payer
			// would sign for a channel smaller than the one recorded.
			name: "nested_capacity_mismatch",
			mutate: func(r *RegistrationRequest) {
				r.ParamsJSON = replaceJSONNumber(t, r.ParamsJSON, "capacity", 1)
			},
			want: RefusalNestedMismatch,
		},
		{
			// (b) the outer registration points at a mint this daemon does not
			// trust. Supplying a trusted URL is what makes this check possible.
			name: "untrusted_outer_mint",
			mutate: func(r *RegistrationRequest) {
				r.Registration.Mint = "https://evil.example"
				r.ParamsJSON = replaceJSONField(t, r.ParamsJSON, "mint", "https://evil.example")
			},
			want: RefusalMintNotTrusted,
		},
		{
			// (b) the trusted keyset itself is a different keyset than the one
			// the params and the registration name.
			name: "keyset_substitution_against_trusted",
			mutate: func(r *RegistrationRequest) {
				// The NUT-02 keyset object is camelCase on the wire (`keysetId`),
				// unlike the registration's snake_case fields. Mutating
				// "keyset_id" here would ADD a field the parser ignores and leave
				// the real id intact — a no-op masquerading as an adversarial
				// case, which is exactly what this test caught the first time.
				r.TrustedKeysetInfo = replaceJSONFieldRaw(t, r.TrustedKeysetInfo, "keysetId", "00deadbeefdeadbe")
			},
			want: RefusalKeysetMismatch,
		},
		{
			// (c) a unit the protocol does not accept.
			name: "unsupported_unit",
			mutate: func(r *RegistrationRequest) {
				r.Registration.Unit = "usd"
				r.ParamsJSON = replaceJSONField(t, r.ParamsJSON, "unit", "usd")
			},
			want: RefusalUnsupportedUnit,
		},
		{
			// (c) zero capacity is not a channel.
			name: "zero_capacity",
			mutate: func(r *RegistrationRequest) {
				r.Registration.Capacity = 0
				r.ParamsJSON = replaceJSONNumber(t, r.ParamsJSON, "capacity", 0)
			},
			want: RefusalZeroCapacity,
		},
		{
			// (c) expired: the clock is SUPPLIED, so expiry is judgeable
			// offline and reproducibly.
			name: "expired",
			mutate: func(r *RegistrationRequest) {
				r.NowUnix = 4102444801
			},
			want: RefusalRegistrationExpired,
		},
		{
			// (c) a channel id that cannot be derived from what was sent.
			name: "channel_id_not_derivable",
			mutate: func(r *RegistrationRequest) {
				r.Registration.SenderPubkey = "not-a-pubkey"
			},
			want: RefusalChannelNotDerivable,
		},
		{
			// (c) a 2-of-2 channel whose two keys are the same key is a
			// self-transfer, not a channel.
			name: "sender_equals_receiver",
			mutate: func(r *RegistrationRequest) {
				r.Registration.SenderPubkey = r.Registration.ReceiverPubkey
			},
			want: RefusalSenderEqualsReceiver,
		},
		{
			// The receiver secret must be a real scalar; a bogus one cannot own
			// any public key.
			name: "receiver_secret_not_a_scalar",
			mutate: func(r *RegistrationRequest) {
				r.ReceiverSecretHex = "zz" + r.ReceiverSecretHex[2:]
			},
			want: RefusalReceiverMismatch,
		},
		{
			// Nested params that are not an object at all.
			name: "nested_params_not_an_object",
			mutate: func(r *RegistrationRequest) {
				r.ParamsJSON = `"not-an-object"`
			},
			// A params blob that is not the protocol's object cannot be parsed
			// into ChannelParameters at all, so the refusal names the derivation
			// it could not perform.
			want: RefusalChannelNotDerivable,
		},
		{
			// Nested params carrying a field the closed shape does not allow:
			// an extra field could move the channel id.
			name: "nested_params_extra_field",
			mutate: func(r *RegistrationRequest) {
				r.ParamsJSON = replaceJSONAddField(t, r.ParamsJSON, "extra_field", "1")
			},
			// The closed nested shape rejects the extra field at deserialization,
			// before any comparison: an unknown field could otherwise move the
			// channel id while looking like agreement.
			want: RefusalChannelNotDerivable,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			req := g.request()
			tc.mutate(&req)
			// A fresh client per case: a refusal keeps the connection usable, but
			// gating each case on its own socket keeps a framing bug from
			// cascading into a misleading second failure.
			client := p.client(t)
			got, err := client.ValidateRegistration(context.Background(), "op-"+tc.name, req)
			if err == nil {
				t.Fatalf("expected refusal %q, got validated values %+v", tc.want, got)
			}
			var refusal *RefusalError
			if !errors.As(err, &refusal) {
				t.Fatalf("want *RefusalError carrying %q, got %T: %v", tc.want, err, err)
			}
			if refusal.Code != tc.want {
				t.Fatalf("refusal code: got %q want %q", refusal.Code, tc.want)
			}
		})
	}
}

// TestRealSidecarRejectsUnknownFieldAndBadFrames proves the request shape is
// closed and the frame bound holds across languages.
func TestRealSidecarRejectsUnknownFieldAndBadFrames(t *testing.T) {
	t.Run("unknown_top_level_field", func(t *testing.T) {
		p := shortRealSidecar(t)
		c := p.client(t)
		g := loadGolden(t)
		// Extra field inside PARAMS: the versioned request type is closed, so
		// this is a caller on a different revision and must fail loudly.
		params := map[string]any{
			"receiver_secret_hex": g.ReceiverSecretHex,
			"trusted_mint_url":    g.TrustedMintURL,
			"trusted_keyset_info": g.TrustedKeysetInfo,
			"registration":        g.Registration,
			"params_json":         g.NestedParamsJSON,
			"now_unix":            1700000000,
			"injected_field":      "1",
		}
		payload, err := json.Marshal(params)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		response, err := c.exchange(context.Background(), MethodValidateRegistration, "req-unknown", "op-unknown", payload)
		if err != nil {
			t.Fatalf("exchange failed before a correlated reply was read: %v", err)
		}
		// A schema violation is a REFUSAL the client can act on, not a transport
		// failure: the caller's frame was readable, so the peer may name it.
		if response.Error != "invalid_request" {
			t.Fatalf("want invalid_request, got %q", response.Error)
		}
		if len(response.Validated) != 0 {
			t.Fatalf("a refused request must carry no validated values: %s", response.Validated)
		}
	})

	t.Run("oversized_frame", func(t *testing.T) {
		p := shortRealSidecar(t)
		c := p.client(t)
		// One frame, larger than the bound, written raw so the CLIENT's own
		// bound cannot be the thing under test.
		huge := fmt.Sprintf(`{"version":1,"request_id":"req-huge","operation_id":"op-huge","method":"validate_registration","params":{"pad":%q}}`+"\n", make([]byte, MaxFrameBytes+1024))
		if _, err := c.conn.Write([]byte(huge)); err != nil {
			t.Fatalf("write: %v", err)
		}
		resp, err := c.readFrame()
		if err != nil {
			if errors.Is(err, ErrFrameTooLarge) {
				return // the sidecar closed without answering: acceptable
			}
			t.Fatalf("read: %v", err)
		}
		var reply struct {
			Error string `json:"error"`
		}
		if err := json.Unmarshal(resp, &reply); err != nil {
			t.Fatalf("reply is not JSON: %v", err)
		}
		if reply.Error != "frame_too_large" && reply.Error != "" {
			t.Fatalf("want frame_too_large, got %q", reply.Error)
		}
	})

	t.Run("malformed_json", func(t *testing.T) {
		p := shortRealSidecar(t)
		c := p.client(t)
		if _, err := c.conn.Write([]byte("{not json}\n")); err != nil {
			t.Fatalf("write: %v", err)
		}
		resp, err := c.readFrame()
		if err != nil {
			t.Fatalf("read: %v", err)
		}
		var reply struct {
			Error string `json:"error"`
		}
		if err := json.Unmarshal(resp, &reply); err != nil {
			t.Fatalf("reply is not JSON: %v", err)
		}
		if reply.Error != "invalid_request" {
			t.Fatalf("want invalid_request, got %q", reply.Error)
		}
	})
}

// replaceJSONField rewrites one field of a JSON object string, for building a
// tampered nested-params blob. It fails the test rather than silently leaving
// the fixture intact, because a mutation that did not happen would turn an
// adversarial case into a duplicate of the happy path.
func replaceJSONField(t *testing.T, blob, field, value string) string {
	t.Helper()
	var obj map[string]json.RawMessage
	if err := json.Unmarshal([]byte(blob), &obj); err != nil {
		t.Fatalf("tamper target is not a JSON object: %v", err)
	}
	// REFUSE a no-op. Writing a field that is not already there leaves every
	// real value untouched, so an "adversarial" case quietly becomes the happy
	// path and its assertion only looks meaningful. The one legitimate ADD (the
	// extra-field case) goes through replaceJSONAddField instead.
	if _, present := obj[field]; !present {
		t.Fatalf("field %q is not present: mutating it would be a no-op", field)
	}
	encoded, err := json.Marshal(value)
	if err != nil {
		t.Fatalf("marshal value: %v", err)
	}
	obj[field] = encoded
	out, err := json.Marshal(obj)
	if err != nil {
		t.Fatalf("marshal tampered blob: %v", err)
	}
	return string(out)
}

// replaceJSONNumber rewrites a field with a JSON NUMBER.
//
// NestedParams deserializes capacity/expiry/etc. as u64, so substituting a
// quoted string fails deserialization and the sidecar refuses with
// `channel_id_not_derivable` before the field comparison ever runs. That makes
// the case look adversarial while testing the wrong branch — the mismatch must
// be TYPED CORRECTLY and semantically wrong to reach `nested_params_mismatch`.
func replaceJSONNumber(t *testing.T, blob, field string, value uint64) string {
	t.Helper()
	var obj map[string]json.RawMessage
	if err := json.Unmarshal([]byte(blob), &obj); err != nil {
		t.Fatalf("tamper target is not a JSON object: %v", err)
	}
	if _, ok := obj[field]; !ok {
		// A mutation of a field that does not exist leaves the fixture intact
		// and silently degrades the case into the happy path.
		t.Fatalf("field %q is not present in the nested params: a no-op mutation", field)
	}
	obj[field] = json.RawMessage(strconv.FormatUint(value, 10))
	out, err := json.Marshal(obj)
	if err != nil {
		t.Fatalf("marshal tampered blob: %v", err)
	}
	return string(out)
}

// replaceJSONAddField adds a field that is not expected to exist. Separate from
// replaceJSONField precisely so "I meant to add" is explicit at the call site.
func replaceJSONAddField(t *testing.T, blob, field, value string) string {
	t.Helper()
	var obj map[string]json.RawMessage
	if err := json.Unmarshal([]byte(blob), &obj); err != nil {
		t.Fatalf("tamper target is not a JSON object: %v", err)
	}
	if _, present := obj[field]; present {
		t.Fatalf("field %q already exists: this case means to ADD one", field)
	}
	encoded, err := json.Marshal(value)
	if err != nil {
		t.Fatalf("marshal value: %v", err)
	}
	obj[field] = encoded
	out, err := json.Marshal(obj)
	if err != nil {
		t.Fatalf("marshal tampered blob: %v", err)
	}
	return string(out)
}

func replaceJSONFieldRaw(t *testing.T, blob json.RawMessage, field, value string) json.RawMessage {
	t.Helper()
	return json.RawMessage(replaceJSONField(t, string(blob), field, value))
}
